CREATE TABLE `ts_timeline_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `repository_id` bigint unsigned NOT NULL,
  `logical_alert_id` bigint unsigned NOT NULL,
  `event_type` tinyint unsigned NOT NULL,
  `event_timestamp` datetime(6) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `commit_oid` varchar(40) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `ref` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `user_id` int unsigned DEFAULT NULL,
  `resolution` tinyint NOT NULL DEFAULT '0',
  `resolution_note` varchar(280) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `file_path` varchar(4096) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `start_line` int unsigned DEFAULT NULL,
  `tool_version_id` bigint unsigned DEFAULT NULL,
  `analysis_id` bigint unsigned DEFAULT NULL,
  `environment` json NOT NULL,
  `workflow_run_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_timeline_events_on_analysis_id` (`analysis_id`,`repository_id`),
  KEY `idx_timeline_events_on_repository_id_logical_id` (`repository_id`,`logical_alert_id`),
  KEY `idx_timeline_events_on_repository_id_ref_logical_id` (`repository_id`,`ref`,`logical_alert_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
